CREATE PROCEDURE TEST_TENANT_MISSING (
    IN  P_CLAIM_ID BIGINT,
    IN  P_TENANT_ID CHAR(8)
)
LANGUAGE SQL
BEGIN
    UPDATE CLAIM
       SET STATUS = 'CLOSED'
     WHERE CLAIM_ID = P_CLAIM_ID
       AND TENANT_ID = P_TENANT_ID;

    UPDATE CLAIM
       SET STATUS = 'CLOSED'
     WHERE CLAIM_ID = P_CLAIM_ID;
END
